class Domain:
    """
    We grow a tree-like data structure. Any named set of contiguous entries in
    this structure is referred to as a domain.

    This class serves as a generic parent class for any other data structure
    occuring in such a tree.

    The class handles the base functionality about name and update procedure
    as well as str and repr display.

    info: see this as an abstract class. Not supposed to be used directly.
    """

    _IDENTIFIER = "Domain"
    _IDENTIFIER_SHORT = "D"
    _enum = 0

    @autoname
    def __init__(self, *, name):
        self._name = name

        # start empty
        self._size = 0

        # contain domains, (nested) keymaps, regions or entries
        self._content = []  # format: [(kseg, domain), ...]

        # remember what you are attached to
        self._parents = []

        # start with False, better safe than sorry
        self._is_ud_flag = False

        # domain can be locked for change
        self._is_locked = False

    @property
    def is_locked(self) -> bool:
        """check if the domain is locked"""
        return self._is_locked

    @property
    def name(self) -> str:
        """
        Access protected variable name.

        :returns: the name."""
        return self._name

    @name.setter
    def name(self, name):
        if self.is_locked:
            raise RuntimeError("Domain is locked!")
        # warnings.warn(
        #     "Bad programmer, bad! But seriously, be careful with renaming."
        # )
        self._name = name

    @property
    def size(self) -> int:
        """
        Access read-only variable size.

        :returns: the size.
        """
        self._update_internals()
        return self._size

    def __str__(self):
        self._update_internals()
        return f"<{self._IDENTIFIER} '{self.name}'>"

    def __repr__(self):
        self._update_internals()
        return f"<{self._IDENTIFIER_SHORT}[{self.name}]>"

    def __len__(self):
        self._update_internals()
        return self._size

    def _update_internals(self, force=False) -> bool:
        """
        Wrapped call to internal update procedure. Skips update if already up to
        date.

        :returns: self, so you can chain calls.
        :raises: RuntimeError if update did not succeed.
        """
        if self.is_ud and not force:
            return True
        self._is_ud_flag = self._update(force=force)
        if not self._is_ud_flag:
            raise RuntimeError("update did not succeed")
        return True

    def _update(self, force=False) -> bool:
        """the actual update procedure"""
        raise NotImplementedError("Subclasses must implement this method")

    def update(self, force=False) -> Self:
        """Placeholder for user update. Overwritten later."""
        self._update_internals(force=force)
        return self

    @property
    def is_ud(self) -> bool:
        """Read-only access to update flag."""
        return self._is_ud_flag

    def flag_ud(self):
        """
        Mark this Domain for update.

        :returns: self, so you can chain calls.
        """
        if self.is_locked:
            raise ValueError("Cannot flag locked domain for update")
        self._is_ud_flag = False
        for parent in self._parents:
            parent.flag_ud()
        return self

    @staticmethod
    def from_file(filename) -> Domain:
        """
        Get the domain object from a file.

        :param filename: the file to read from.
        :returns: the loaded Domain object, flagged for update.
        :raises: FileNotFoundError (from pickle) if the file does not exist.
        :raises: RuntimeError if the update call did not succeed.
        """
        dom = None
        with open(filename, "rb") as handle:
            dom = pickle.load(handle)
            dom.flag_ud()
            dom.__class__._enum += 1
            if not dom.update():
                raise RuntimeError("Critical: Update did not succeed")
        assert dom is not None
        return dom

    def to_file(self, filename) -> Self:
        """
        Write the domain to a file.

        :param filename: the file to write to.
        :returns: self, so you can chain calls.
        :raises: IOError (from pickle) if the file could not be opened or
                 written to.
        """
        self._update_internals()
        with open(filename, "wb") as handle:
            pickle.dump(self, handle)
        return self

    def add_parent(self, parent) -> Self:
        """
        Add a parent domain if not yet added.

        :param parent: the parent domain.
        :returns: self, so you can chain calls.
        :raises: ValueError if parent is not a Domain.
        """
        if not isinstance(parent, Domain):
            raise ValueError("parent must be a Domain")
        if parent not in self._parents:
            self._parents.append(parent)
        return self

    def keys(self, recursive=False, prefix: Key | None = None):
        """
        The generator equivalent to dict's keys function.

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix)
        return
        yield

    def items(self, recursive=False, prefix: Key | None = None):
        """
        The generator equivalent to dict's items function

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix), self
        return
        yield

    def values(self, recursive=False):
        """
        The generator equivalent to dict's values function

        :param recursive: whether to forward recursive call for each domain
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            yield self
        return
        yield

    def lock(self) -> Self:
        """
        The domain can be locked to avoid further change.
        Attempts an update before locking.

        :returns: self, to place it in chained calls
        """
        self.update()
        for content in self._content:
            content.lock()
        self._is_locked = True
        return self

    def tree(self, level=0, key=None):
        """a generator that reveals tree information"""
        yield level, key, self
        for key, domain in self.items():
            yield from domain.tree(level=level + 1, key=key)


