class KeyMap(Domain):
    """Keymap class description"""

    _IDENTIFIER = "KeyMap"
    _IDENTIFIER_SHORT = "KM"
    _enum = 0

    @autoname
    def __init__(self, *, name=None):
        super().__init__(name=name)

        # lookup tables
        self._off2dom = []  # translate from offset to dom and remaining offset
        self._off2key = []  # translate from offset to key
        self._key2off = {}  # translate the key to its offset
        self._key2dom = {}  # key objects are keys to doms

        # reset
        self._reset()

        self._kseg_factory = self._create_keyseg_factory(name)

    def _reset(self):
        """Reset anything that has to do with counters and offsets."""
        assert not self.is_locked
        self._is_ud_flag = False
        self._size = 0
        self._off2dom = []
        self._off2key = []
        self._key2off = {}
        self._key2dom = {}

    def key(self, keylike, /):
        """
        Generate a key object from the KeyMaps own key factory.

        :param label: the label of the key to generate.
        :returns: the Key object.
        """
        label = keylike
        if isinstance(label, Key):
            label = label.onlylabel()
        elif isinstance(label, _KeySegment):
            label = label.label
        else:
            if not isinstance(label, Hashable):
                raise ValueError("keylike must be a Hashable object")
        return Key(self._kseg_factory(label))

    def _tagged_keyseg(self, label):
        return self._kseg_factory(label)

    def _create_keyseg_factory(self, name) -> Type:
        """The keygenerator class can be tagged by a parent."""
        # inherit from _KeySegment and set self as the default parent
        factory = type(
            f"auto_KeyGen_{name}",
            (_KeySegment,),
            {
                "__doc__": f"key generator for keymap '{name}'.",
            },
            parent=self,
        )
        return factory

    def reorder(self, function) -> Self:
        """reorder the arrangement of keys in the map by sorting function.
        The function must take a key object as an input and return a sorting id.
        :param function: the sorting function
        :returns: self, so you can chain calls
        """
        if self.is_locked:
            raise ValueError("Cannot reorder locked KeyMap")
        aux = sorted(
            [
                (sort_id, key, keymap)
                for key, keymap in self._content
                if (sort_id := function(Key(key), keymap)) is not None
            ]
        )
        self._content = [(key, keymap) for _, key, keymap in aux]
        return self

    def entry(self, keylike, /):
        """
        Add a new entry a keylike input.
        The keylike must be a Hashable object or a Key.

        :param keylike: the key to add
        :returns: self, so you can chain calls"""
        if self.is_locked:
            raise ValueError("Cannot add entry to a locked domain")
        key = self.key(keylike)
        self.link(key, Entry(name=key.onlylabel()))
        return self

    def extend(self, domain, autorename=True):
        """
        Extend by a domain and derive the corresponding key from its name.
        If the autorename flag is set, counting numbers are attached to the
        name if the name is already taken.

        :param keymap: the keymap to extend.
        :param autorename: whether to automatically rename if the name is
                           already taken.
        :returns: self, so you can chain calls.
        """
        if self.is_locked:
            raise ValueError("Cannot extend locked domain")
        if not isinstance(domain, Domain):
            raise ValueError("Not a Domain")
        name = domain.name
        kseg = self._tagged_keyseg(name)

        # find a working kseg or raise exception
        if kseg in self:
            if autorename:
                num = 1
                while kseg in self:
                    num += 1
                    name = f"{domain.name}.{num}"
                    kseg = self._tagged_keyseg(name)
            else:
                raise KeyError(f"Key '{kseg.label}' already exists")
        self._link(kseg, domain)
        return self

    def link(self, keylike, /, domain, no_override=True):
        """
        Create a link to domain object via a key in the keymap.
        The key is either given or generated from the domains name.
        If no domain is given, an entry is generated at the key location.
        The key object is copied when applied.

        :param keylike: the key to add.
        :param domain: the domain to add.
        :param no_override: whether to raise an exception if the key already
                            exists.
        :returns: self, so you can chain calls.
        """

        if self.is_locked:
            raise ValueError("Cannot add to a locked keymap")

        # use a kseg from this map
        kseg = self._to_tagged_keyseg(keylike)

        if domain is None:
            # default thing to add is an entry
            domain = Entry(name=str(kseg.label))

        # check if key is duplicate
        if no_override:
            if kseg in self:
                raise KeyError(f"Key '{kseg}' already exists")
        self._link(kseg, domain)
        return self

    def _link(self, kseg, domain):
        """
        Places a domain at a keyseg and manage the parent. Flag for update.
        No overwrite checks are performed!
        """

        # acutal append
        self._append(kseg, domain)

        # register the current domain as a parent to the included domain
        domain.add_parent(self)
        self.flag_ud()
        return self

    def _append(self, kseg, domain):
        """Internal append, no checks applied except kseg format."""
        assert isinstance(kseg, _KeySegment)
        assert isinstance(domain, Domain)
        self._content.append((kseg, domain))

    def _update(self, force=False) -> bool:
        """
        Internal update routine. Go through content and refill the indexing
        dictionaries while appending.
        """
        self._reset()
        offset_pointer = 0

        # go through domains in content
        for tkey, domain in self._content:
            ret = domain.update(force=force)
            if not ret:
                raise RuntimeError("domain update failed")
            if domain.size <= 0:
                warnings.warn(f"domain {domain} is empty")
                continue

            # move into the selected domain
            self._key2dom[tkey] = domain
            self._key2off[tkey] = offset_pointer
            for offset in range(len(domain)):
                self._off2dom.append((domain, offset))
                self._off2key.append((tkey))
                offset_pointer += 1
        assert len(self._off2dom) == offset_pointer
        self._size = offset_pointer
        return True

    def __getitem__(self, key):
        _, entry = self.goto(key)
        return entry

    def __contains__(self, keylike):
        kseg = self._to_tagged_keyseg(keylike)
        for tkey, _ in self._content:
            if tkey == kseg:
                return True
        return False

    def _to_tagged_keyseg(self, keylike):
        """Transform a keylike into a (tagged) KeySegment."""

        label = keylike  # assume hashable if no other conditional checks out

        # check if key
        if isinstance(keylike, Key):
            if len(keylike) != 1:
                raise ValueError("Key cannot be a chained key")
            label = keylike.onlylabel()

        # check if keysegment
        if isinstance(keylike, _KeySegment):
            label = keylike.label

        # use a kseg from this map
        return self._tagged_keyseg(label)

    def keys(self, recursive: bool = False, prefix: Key | None = None):
        """
        The generator equivalent to dict's keys function.

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we COULD have prefix: Key = Key() in the args list, as the empty key
        # as default could be a monad, but it is cleaner like that.
        self._update_internals()
        if prefix is None:
            prefix = Key()
        for key, dom in self._key2dom.items():
            if recursive:
                yield from dom.keys(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(prefix, key)

    def items(self, recursive: bool = False, prefix: Key | None = None):
        """
        The generator equivalent to dict's items function

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        self._update_internals()
        if prefix is None:
            prefix = Key()
        for key, dom in self._key2dom.items():
            if recursive:
                yield from dom.items(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(key), dom

    def values(self, recursive: bool = False):
        """
        The generator equivalent to dict's values function

        :param recursive: whether to forward recursive call for each domain
        :returns: a generator of Key objects
        """
        self._update_internals()
        for _, dom in self._key2dom.items():
            if recursive:
                yield from dom.values(recursive=True)
            else:
                yield dom

    def _key2offdom(self, *keys):
        """
        Get position and domain from key

        :param keys: keys to find
        :returns: a tuple of (position, Domain)"""
        self._update_internals()
        key = Key(*keys)
        current_obj = self
        current_pos = 0
        for kmap, kseg in key._unchain():
            if kmap is not None:
                if kmap != current_obj:
                    raise KeyError(
                        f"Tagged key {kseg.label} not from keymap {current_obj}"
                    )
            if kseg not in current_obj._key2off:
                raise KeyError(
                    f"Cannot find key {kseg} in domain '{current_obj}'"
                )
            current_pos += current_obj._key2off[kseg]
            current_obj = current_obj._key2dom[kseg]

        return current_pos, current_obj

    def _off2keydom(self, offset: int, *, _collect=None):
        """
        Get key and domain from position

        :param offset: the position to find
        :returns: (Domain, Key)
        """
        if _collect is None:
            _collect = Key()
        if isinstance(self, Entry) or not self._key2dom:
            assert isinstance(_collect, Key)
            return _collect, self  # RETURN
        this_key = self._off2key[offset]
        next_domain, remaining_offset = self._off2dom[offset]
        return next_domain._off2keydom(
            remaining_offset, _collect=Key(_collect, this_key)
        )

    # public routines
    # ===============

    def key2off(self, *keys):
        """key to offset"""
        off, _ = self._key2offdom(*keys)
        return off

    def key2dom(self, *keys):
        """key to domain"""
        _, domain = self._key2offdom(*keys)
        return domain

    def goto(self, *keys):
        """goto a key and find both offset and domain"""
        return self._key2offdom(*keys)

    def off2key(self, offs: int):
        """offset to key"""
        key, _ = self._off2keydom(offs, _collect=Key())
        return key

    def off2dom(self, offs: int):
        """offset to domain"""
        _, domain = self._off2keydom(offs, _collect=Key())
        return domain

    def proceed(self, offs: int):
        """proceed by an offset and find key and domain"""
        return self._off2keydom(offs, _collect=Key())


